import { useEffect, useRef, useState, useCallback } from "react";
import L from "leaflet";
import "leaflet/dist/leaflet.css";

const TILE_LAYERS = {
  street: {
    url: "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
    attribution: "© OpenStreetMap contributors",
    label: "🗺 Map",
  },
  satellite: {
    url: "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
    attribution: "© Esri",
    label: "🛰 Satellite",
  },
};

const CROP_OPTIONS = [
  "Rice",
  "Tomato",
  "Cotton",
  "Banana",
  "Groundnut",
  "Maize",
  "Sugarcane",
];

export default function FarmMap() {
  // ─────────────────────────────────────────────
  // STATE
  // ─────────────────────────────────────────────
  const [pickerOpen, setPickerOpen] = useState(false);
  const [tileMode, setTileMode] = useState("street");

  const [farms, setFarms] = useState([]);

  const [form, setForm] = useState({
    name: "",
    crop: "Rice",
    size: "",
  });

  const [pickerCoords, setPickerCoords] = useState(null);

  // ─────────────────────────────────────────────
  // REFS
  // ─────────────────────────────────────────────
  const mapRef = useRef(null);
  const pickerRef = useRef(null);

  const mapInstance = useRef(null);
  const pickerInstance = useRef(null);

  const mainTileRef = useRef(null);
  const pickerTileRef = useRef(null);

  const markersRef = useRef([]);

  // ─────────────────────────────────────────────
  // MAIN MAP INIT
  // ─────────────────────────────────────────────
  const initMainMap = useCallback(() => {
    if (!mapRef.current) return;

    // Prevent duplicate map initialization
    if (mapInstance.current) return;

    const map = L.map(mapRef.current, {
      zoomControl: true,
    }).setView([9.9252, 78.1198], 13);

    mainTileRef.current = L.tileLayer(
      TILE_LAYERS[tileMode].url,
      {
        attribution: TILE_LAYERS[tileMode].attribution,
        maxZoom: 22,
      }
    ).addTo(map);

    mapInstance.current = map;

    // USER LOCATION
    navigator.geolocation?.getCurrentPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lon = pos.coords.longitude;

        map.flyTo([lat, lon], 16, {
          duration: 1.5,
        });

        L.marker([lat, lon])
          .addTo(map)
          .bindPopup("📍 Your Location");
      },
      () => {},
      {
        enableHighAccuracy: true,
      }
    );
  }, [tileMode]);

  // ─────────────────────────────────────────────
  // LOAD MAIN MAP
  // ─────────────────────────────────────────────
  useEffect(() => {
    if (!pickerOpen) {
      setTimeout(() => {
        initMainMap();

        // refresh rendering
        mapInstance.current?.invalidateSize(true);
      }, 150);
    }
  }, [pickerOpen, initMainMap]);

  // ─────────────────────────────────────────────
  // TILE CHANGE MAIN MAP
  // ─────────────────────────────────────────────
  useEffect(() => {
    if (!mapInstance.current) return;

    mainTileRef.current?.remove();

    mainTileRef.current = L.tileLayer(
      TILE_LAYERS[tileMode].url,
      {
        attribution: TILE_LAYERS[tileMode].attribution,
        maxZoom: 22,
      }
    ).addTo(mapInstance.current);
  }, [tileMode]);

  // ─────────────────────────────────────────────
  // ADD FARM MARKERS
  // ─────────────────────────────────────────────
  useEffect(() => {
    if (!mapInstance.current) return;

    // remove old markers
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    farms.forEach((farm) => {
      const marker = L.marker([farm.lat, farm.lon])
        .addTo(mapInstance.current)
        .bindPopup(`
          <b>${farm.name}</b><br/>
          🌾 ${farm.crop}<br/>
          📏 ${farm.size} acres
        `);

      markersRef.current.push(marker);
    });
  }, [farms]);

  // ─────────────────────────────────────────────
  // PICKER MAP INIT
  // ─────────────────────────────────────────────
  useEffect(() => {
    if (!pickerOpen) return;

    setTimeout(() => {
      if (!pickerRef.current) return;

      // destroy old picker safely
      if (pickerInstance.current) {
        pickerInstance.current.remove();
        pickerInstance.current = null;
      }

      const map = L.map(pickerRef.current, {
        zoomControl: true,
      }).setView([9.9252, 78.1198], 15);

      pickerTileRef.current = L.tileLayer(
        TILE_LAYERS[tileMode].url,
        {
          attribution: TILE_LAYERS[tileMode].attribution,
          maxZoom: 22,
        }
      ).addTo(map);

      pickerInstance.current = map;

      // center tracking
      const updateCenter = () => {
        const c = map.getCenter();

        setPickerCoords({
          lat: c.lat,
          lon: c.lng,
        });
      };

      updateCenter();

      map.on("move", updateCenter);

      navigator.geolocation?.getCurrentPosition(
        (pos) => {
          map.flyTo(
            [pos.coords.latitude, pos.coords.longitude],
            18,
            {
              duration: 1.2,
            }
          );
        },
        () => {},
        {
          enableHighAccuracy: true,
        }
      );

      setTimeout(() => {
        map.invalidateSize(true);
      }, 300);
    }, 100);

    return () => {
      if (pickerInstance.current) {
        pickerInstance.current.remove();
        pickerInstance.current = null;
      }
    };
  }, [pickerOpen, tileMode]);

  // ─────────────────────────────────────────────
  // SAVE FARM
  // ─────────────────────────────────────────────
  const saveFarm = () => {
    if (!pickerCoords) {
      alert("Move map to select location");
      return;
    }

    if (!form.name.trim()) {
      alert("Enter farm name");
      return;
    }

    const farm = {
      id: Date.now(),
      ...form,
      lat: pickerCoords.lat,
      lon: pickerCoords.lon,
    };

    setFarms((prev) => [...prev, farm]);

    setForm({
      name: "",
      crop: "Rice",
      size: "",
    });

    setPickerOpen(false);
  };

  // ─────────────────────────────────────────────
  // MAIN VIEW
  // ─────────────────────────────────────────────
  if (!pickerOpen) {
    return (
      <div
        style={{
          padding: 20,
          background: "#f4f6f8",
          minHeight: "100vh",
        }}
      >
        {/* HEADER */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginBottom: 14,
            gap: 10,
            flexWrap: "wrap",
          }}
        >
          <div>
            <h2
              style={{
                margin: 0,
                fontSize: 24,
              }}
            >
              🗺 Farm Map
            </h2>

            <div
              style={{
                color: "#666",
                fontSize: 13,
                marginTop: 4,
              }}
            >
              Smart GPS farm management
            </div>
          </div>

          <div
            style={{
              display: "flex",
              gap: 10,
            }}
          >
            <button
              onClick={() =>
                setTileMode((m) =>
                  m === "street"
                    ? "satellite"
                    : "street"
                )
              }
              style={buttonStyle}
            >
              {
                TILE_LAYERS[
                  tileMode === "street"
                    ? "satellite"
                    : "street"
                ].label
              }
            </button>

            <button
              onClick={() => setPickerOpen(true)}
              style={{
                ...buttonStyle,
                background: "#1a7a3a",
                color: "#fff",
                border: "none",
              }}
            >
              + Add Farm
            </button>
          </div>
        </div>

        {/* MAP */}
        <div
          ref={mapRef}
          style={{
            width: "100%",
            height: 460,
            borderRadius: 18,
            overflow: "hidden",
            background: "#ddd",
            marginBottom: 20,
            boxShadow:
              "0 8px 24px rgba(0,0,0,0.12)",
          }}
        />

        {/* FARM LIST */}
        <div
          style={{
            display: "grid",
            gap: 12,
          }}
        >
          {farms.length === 0 && (
            <div
              style={{
                padding: 30,
                background: "#fff",
                borderRadius: 14,
                textAlign: "center",
                color: "#888",
              }}
            >
              No farms added yet
            </div>
          )}

          {farms.map((farm) => (
            <div
              key={farm.id}
              style={{
                background: "#fff",
                borderRadius: 14,
                padding: 16,
                boxShadow:
                  "0 2px 8px rgba(0,0,0,0.08)",
              }}
            >
              <div
                style={{
                  fontWeight: 700,
                  fontSize: 16,
                }}
              >
                🚜 {farm.name}
              </div>

              <div
                style={{
                  marginTop: 6,
                  color: "#666",
                  fontSize: 13,
                }}
              >
                🌾 {farm.crop}
              </div>

              <div
                style={{
                  marginTop: 4,
                  color: "#666",
                  fontSize: 13,
                }}
              >
                📏 {farm.size} acres
              </div>

              <div
                style={{
                  marginTop: 4,
                  color: "#999",
                  fontSize: 11,
                }}
              >
                {farm.lat.toFixed(5)} ,
                {" "}
                {farm.lon.toFixed(5)}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // ─────────────────────────────────────────────
  // PICKER SCREEN
  // ─────────────────────────────────────────────
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "#fff",
      }}
    >
      {/* TOPBAR */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 12,
          padding: 16,
          borderBottom: "1px solid #eee",
        }}
      >
        <button
          onClick={() => setPickerOpen(false)}
          style={{
            border: "none",
            background: "none",
            fontSize: 22,
            cursor: "pointer",
          }}
        >
          ←
        </button>

        <div>
          <div
            style={{
              fontWeight: 700,
              fontSize: 16,
            }}
          >
            📍 Select Farm Location
          </div>

          <div
            style={{
              fontSize: 12,
              color: "#888",
            }}
          >
            Move map to your farm
          </div>
        </div>
      </div>

      {/* PICKER MAP */}
      <div
        style={{
          position: "relative",
        }}
      >
        <div
          ref={pickerRef}
          style={{
            width: "100%",
            height: 430,
            background: "#ddd",
          }}
        />

        {/* CENTER PIN */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform:
              "translate(-50%, -100%)",
            pointerEvents: "none",
            zIndex: 999,
          }}
        >
          <div
            style={{
              background: "#1a7a3a",
              color: "#fff",
              padding: "8px 12px",
              borderRadius: 10,
              fontSize: 13,
              fontWeight: 700,
              boxShadow:
                "0 6px 18px rgba(0,0,0,0.3)",
            }}
          >
            📍 Farm Here
          </div>

          <div
            style={{
              width: 4,
              height: 20,
              background: "#1a7a3a",
              margin: "0 auto",
            }}
          />

          <div
            style={{
              width: 12,
              height: 12,
              borderRadius: "50%",
              background: "#1a7a3a",
              margin: "0 auto",
            }}
          />
        </div>
      </div>

      {/* FORM */}
      <div
        style={{
          padding: 18,
          display: "grid",
          gap: 14,
        }}
      >
        <input
          placeholder="Farm Name"
          value={form.name}
          onChange={(e) =>
            setForm({
              ...form,
              name: e.target.value,
            })
          }
          style={inputStyle}
        />

        <select
          value={form.crop}
          onChange={(e) =>
            setForm({
              ...form,
              crop: e.target.value,
            })
          }
          style={inputStyle}
        >
          {CROP_OPTIONS.map((crop) => (
            <option key={crop}>
              {crop}
            </option>
          ))}
        </select>

        <input
          type="number"
          placeholder="Farm Size (acres)"
          value={form.size}
          onChange={(e) =>
            setForm({
              ...form,
              size: e.target.value,
            })
          }
          style={inputStyle}
        />

        {pickerCoords && (
          <div
            style={{
              fontSize: 12,
              color: "#666",
            }}
          >
            📌 {pickerCoords.lat.toFixed(6)}
            {" , "}
            {pickerCoords.lon.toFixed(6)}
          </div>
        )}

        <button
          onClick={saveFarm}
          style={{
            background: "#1a7a3a",
            color: "#fff",
            border: "none",
            padding: 16,
            borderRadius: 14,
            fontWeight: 700,
            fontSize: 15,
            cursor: "pointer",
          }}
        >
          ✅ Save Farm
        </button>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────
// STYLES
// ─────────────────────────────────────────────
const buttonStyle = {
  padding: "10px 16px",
  borderRadius: 10,
  border: "1px solid #ddd",
  background: "#fff",
  cursor: "pointer",
  fontWeight: 600,
};

const inputStyle = {
  width: "100%",
  padding: 14,
  borderRadius: 12,
  border: "1px solid #ddd",
  fontSize: 14,
  outline: "none",
};
